var C = ARISTO.colors;
var P = 20;
var lenIn = document.getElementById('len');
var widIn = document.getElementById('wid');
var lenv = document.getElementById('lenv');
var widv = document.getElementById('widv');
var readout = document.getElementById('readout');
var bestEl = document.getElementById('best');
var bestArea = 0;

function fmt(n) {
  var r = Math.round(n * 10) / 10;
  return (Math.abs(r - Math.round(r)) < 0.001) ? String(Math.round(r)) : r.toFixed(1);
}

function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

var plot = ARISTO.canvas(document.getElementById('plot'), function (ctx, w, h) {
  var L = +lenIn.value, W = +widIn.value;
  var maxDim = 10;
  var u = Math.min(w / (maxDim + 1), h / (maxDim + 1));
  var ox = (w - L * u) / 2;
  var oy = (h - W * u) / 2;

  ctx.fillStyle = C.sunk;
  ctx.fillRect(0, 0, w, h);

  ctx.strokeStyle = C.accentText;
  ctx.fillStyle = C.accent;
  ctx.globalAlpha = 0.35;
  ctx.fillRect(ox, oy, L * u, W * u);
  ctx.globalAlpha = 1;

  ctx.lineWidth = 1;
  ctx.strokeStyle = C.line;
  for (var i = 0; i <= Math.round(L); i++) {
    var x = ox + i * u;
    ctx.beginPath(); ctx.moveTo(x, oy); ctx.lineTo(x, oy + W * u); ctx.stroke();
  }
  for (var j = 0; j <= Math.round(W); j++) {
    var y = oy + j * u;
    ctx.beginPath(); ctx.moveTo(ox, y); ctx.lineTo(ox + L * u, y); ctx.stroke();
  }

  ctx.strokeStyle = C.accentText;
  ctx.lineWidth = 3;
  ctx.strokeRect(ox, oy, L * u, W * u);

  ctx.font = '600 13px system-ui, sans-serif';
  ctx.fillStyle = C.ink;
  ctx.textAlign = 'center';
  ctx.fillText('L = ' + fmt(L), ox + (L * u) / 2, oy - 8 > 12 ? oy - 8 : 14);
  ctx.save();
  ctx.translate(ox - 10, oy + (W * u) / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillText('W = ' + fmt(W), 0, 0);
  ctx.restore();
  ctx.textAlign = 'left';
}, 0.55);

function syncFromLength() {
  var L = clamp(+lenIn.value, 1, 9);
  var W = clamp((P / 2) - L, 1, 9);
  lenIn.value = L;
  widIn.value = W;
}
function syncFromWidth() {
  var W = clamp(+widIn.value, 1, 9);
  var L = clamp((P / 2) - W, 1, 9);
  widIn.value = W;
  lenIn.value = L;
}

function update(source) {
  if (source === 'len') syncFromLength();
  else if (source === 'wid') syncFromWidth();

  var L = +lenIn.value, W = +widIn.value;
  var area = Math.round(L * W * 100) / 100;
  if (area > bestArea) {
    bestArea = area;
    bestEl.textContent = fmt(bestArea);
  }
  lenv.textContent = fmt(L);
  widv.textContent = fmt(W);
  readout.textContent = 'Length ' + fmt(L) + ', Width ' + fmt(W) + ', Area ' + fmt(area) + ' (perimeter ' + fmt(2 * (L + W)) + ')';
  plot.redraw();
}

lenIn.addEventListener('input', function () { update('len'); });
widIn.addEventListener('input', function () { update('wid'); });
update();
